from scipy.optimize import least_squares
t=df['t'].values; P=df['P'].values; y=df['dP_dt'].values
sy=np.var(y)
structs={
 'sin_P_and_P^q': lambda p: p[4]*np.sin(p[7]*t)*P**p[5] + p[6]*P**p[8],
 'sin_P_and_sqrtt': lambda p: p[4]*np.sin(p[7]*t)*P**p[5] + p[6]*np.sqrt(t)*P**p[8],
 'cos_P_and_P^q': lambda p: p[4]*np.cos(p[7]*t)*P**p[5] + p[6]*P**p[8],
 'tP_and_P^q': lambda p: p[4]*t*P**p[5] + p[6]*P**p[8]*np.sin(p[7]*t),
 'logt_P': lambda p: p[4]*np.log(t)*P**p[5] + p[6]*np.sin(p[7]*t)*P**p[8],
}
out={}
for name,g in structs.items():
    rng=np.random.default_rng(2); best=None
    for trial in range(120):
        p0=[rng.normal()*2,abs(rng.normal())+0.05,rng.normal(),abs(rng.normal())+0.05,rng.normal(),rng.uniform(-1,3),rng.normal(),rng.uniform(0.1,3),rng.uniform(-1,3)]
